package com.eventpulse.handler;
import com.amazonaws.services.lambda.runtime.Context; import com.amazonaws.services.lambda.runtime.RequestHandler; import com.amazonaws.services.lambda.runtime.events.*; import com.eventpulse.config.*; import com.eventpulse.dto.*; import com.eventpulse.exception.*; import com.eventpulse.model.Event; import com.eventpulse.repository.*; import com.eventpulse.service.*; import com.eventpulse.util.ResponseUtil; import java.util.*;
public class EventHandler implements RequestHandler<APIGatewayV2HTTPEvent,APIGatewayV2HTTPResponse> {
 private final EventService events; private final RegistrationService registrations; private final EventLifecycleService lifecycle; private final UserService users; private final DashboardService dashboard; private final CognitoProfileService cognitoProfiles;
 public EventHandler(){var db=DynamoDbConfig.enhancedClient();var eventRepository=new EventRepository(db,DynamoDbConfig.table("EVENTS_TABLE","EventPulse-Events"));events=new EventService(eventRepository);var rr=new RegistrationRepository(db,DynamoDbConfig.table("REGISTRATIONS_TABLE","EventPulse-Registrations"));var ur=new UserRepository(db,DynamoDbConfig.table("USERS_TABLE","EventPulse-Users"));registrations=new RegistrationService(rr,events);dashboard=new DashboardService(eventRepository,rr);users=new UserService(ur);cognitoProfiles=new CognitoProfileService(CognitoConfig.client());var ns=new NotificationService(SesConfig.client(),SesConfig.sender(),System.getenv("SES_CONFIGURATION_SET"),new NotificationRepository(db,DynamoDbConfig.table("NOTIFICATIONS_TABLE","EventPulse-Notifications")),rr,ur);var scheduler=new EventScheduleService(SchedulerConfig.client(),SchedulerConfig.group(),requiredEnv("REMINDER_FUNCTION_ARN"),requiredEnv("SCHEDULER_EXECUTION_ROLE_ARN"));lifecycle=new EventLifecycleService(ns,scheduler);}
 public EventHandler(EventService e,RegistrationService r){this(e,r,null,null,null,null);} public EventHandler(EventService e,RegistrationService r,EventLifecycleService l){this(e,r,l,null,null,null);} public EventHandler(EventService e,RegistrationService r,EventLifecycleService l,UserService u){this(e,r,l,u,null,null);} public EventHandler(EventService e,RegistrationService r,EventLifecycleService l,UserService u,DashboardService d){this(e,r,l,u,d,null);} public EventHandler(EventService e,RegistrationService r,EventLifecycleService l,UserService u,DashboardService d,CognitoProfileService cp){events=e;registrations=r;lifecycle=l;users=u;dashboard=d;cognitoProfiles=cp;}
 @Override public APIGatewayV2HTTPResponse handleRequest(APIGatewayV2HTTPEvent req,Context ctx){try{String method=req.getRequestContext().getHttp().getMethod(),path=req.getRawPath();Map<String,String> p=req.getPathParameters()==null?Map.of():req.getPathParameters();String id=p.get("eventId");switch(method+" "+path){case "GET /events"-> {return ResponseUtil.response(200,events.list().stream().map(EventResponse::from).toList());}case "GET /admin/dashboard"->{user(req);requireAdmin(req);if(dashboard==null)return ResponseUtil.error(503,"INTEGRATION_UNAVAILABLE","Dashboard integration is unavailable");return ResponseUtil.response(200,dashboard.summary());}case "POST /events"->{requireAdmin(req);var b=ResponseUtil.JSON.readValue(requiredBody(req),CreateEventRequest.class);syncProfile(req);Event e=events.create(b,user(req));if(lifecycle!=null)try{lifecycle.created(e);}catch(ScheduleSyncException scheduleFailure){return schedulePending(e);}return ResponseUtil.response(201,EventResponse.from(e));}default->{if(id!=null&&path.endsWith("/schedule-reconciliation")&&method.equals("POST")){requireAdmin(req);if(lifecycle==null)return ResponseUtil.error(503,"INTEGRATION_UNAVAILABLE","Scheduler integration is unavailable");lifecycle.reconcile(events.get(id));return ResponseUtil.response(200,Map.of("eventId",id,"scheduleSyncStatus","SYNCED"));}if(id!=null&&path.endsWith("/announcements")&&method.equals("POST")){requireAdmin(req);if(lifecycle==null)return ResponseUtil.error(503,"INTEGRATION_UNAVAILABLE","Notification integration is unavailable");Event event=events.get(id);if("CANCELLED".equals(event.getStatus()))return ResponseUtil.error(409,"EVENT_CANCELLED","Cannot announce a cancelled event");List<com.eventpulse.model.NotificationRecord> sent=lifecycle.announce(event);long accepted=sent.stream().filter(n->"ACCEPTED_BY_SES".equals(n.getStatus())).count();return ResponseUtil.response(200,Map.of("eventId",id,"attempted",sent.size(),"acceptedBySes",accepted));}if(id!=null&&path.endsWith("/registrations")&&method.equals("POST")){syncProfile(req);return ResponseUtil.response(201,registrations.register(id,user(req)));}if(id!=null&&path.endsWith("/registrations")&&method.equals("GET")){requireAdmin(req);return ResponseUtil.response(200,registrations.forEvent(id));}if(id!=null&&method.equals("GET"))return ResponseUtil.response(200,EventResponse.from(events.get(id)));if(id!=null&&method.equals("PUT")){requireAdmin(req);var b=ResponseUtil.JSON.readValue(requiredBody(req),UpdateEventRequest.class);Event before=events.get(id);String oldStart=before.getStartDateTime(),oldEnd=before.getEndDateTime();Event after=events.update(id,b);if(lifecycle!=null){Event previous=new Event();previous.setStartDateTime(oldStart);previous.setEndDateTime(oldEnd);try{lifecycle.updated(previous,after);}catch(ScheduleSyncException scheduleFailure){return schedulePending(after);}}return ResponseUtil.response(200,EventResponse.from(after));}if(id!=null&&method.equals("DELETE")){requireAdmin(req);Event cancelled=events.cancel(id);if(lifecycle!=null)try{lifecycle.cancelled(cancelled);}catch(ScheduleSyncException scheduleFailure){return schedulePending(cancelled);}return ResponseUtil.response(200,EventResponse.from(cancelled));}return ResponseUtil.error(404,"NOT_FOUND","Route not found");}}}catch(Exception e){return handleError(e);}}
 private static APIGatewayV2HTTPResponse schedulePending(Event event){return ResponseUtil.response(202,Map.of("event",EventResponse.from(event),"scheduleSyncStatus","PENDING","reconciliationPath","/events/"+event.getEventId()+"/schedule-reconciliation"));}
 private void syncProfile(APIGatewayV2HTTPEvent request){if(users==null)return;String subject=user(request);var profile=cognitoProfiles.getCurrentUser(accessToken(request),subject);users.get(subject,profile.verifiedEmail(),profile.name(),isAdmin(request));}
 private static String requiredEnv(String name){String value=System.getenv(name);if(value==null||value.isBlank())throw new IllegalStateException(name+" must be configured");return value;}
 private static String requiredBody(APIGatewayV2HTTPEvent r){if(r.getBody()==null||r.getBody().isBlank())throw new ValidationException("Request body is required");return r.getBody();}
 static Map<?,?> claims(APIGatewayV2HTTPEvent r){try{Object c=r.getRequestContext().getAuthorizer().getJwt().getClaims();if(c instanceof Map<?,?> m)return m;}catch(Exception ignored){}return Map.of();}
 static String user(APIGatewayV2HTTPEvent r){Object sub=claims(r).get("sub");if(sub!=null&&!sub.toString().isBlank())return sub.toString();throw new AuthorizationException(401,"Authenticated user context is required");}
 static String accessToken(APIGatewayV2HTTPEvent r){String authorization=null;if(r.getHeaders()!=null)for(var entry:r.getHeaders().entrySet())if("authorization".equalsIgnoreCase(entry.getKey())){authorization=entry.getValue();break;}if(authorization==null||!authorization.regionMatches(true,0,"Bearer ",0,7)||authorization.substring(7).isBlank())throw new AuthorizationException(401,"Authenticated Cognito access token is required");return authorization.substring(7).trim();}
 static boolean isAdmin(APIGatewayV2HTTPEvent r){Object groups=claims(r).get("cognito:groups");if(groups instanceof Collection<?> c&&c.contains("ADMIN"))return true;return groups!=null&&Arrays.stream(groups.toString().replace("[","").replace("]","").replace("\"","").split(",")).map(String::trim).anyMatch("ADMIN"::equals);}
 static void requireAdmin(APIGatewayV2HTTPEvent r){if(!isAdmin(r))throw new AuthorizationException(403,"Administrator role is required");}
 static APIGatewayV2HTTPResponse handleError(Exception e){if(e instanceof EventNotFoundException)return ResponseUtil.error(404,"EVENT_NOT_FOUND",e.getMessage());if(e instanceof AuthorizationException a)return ResponseUtil.error(a.status(),"ACCESS_DENIED",e.getMessage());if(e instanceof ValidationException||e instanceof IllegalArgumentException||e instanceof com.fasterxml.jackson.core.JsonProcessingException)return ResponseUtil.error(400,"INVALID_REQUEST",e.getMessage());if(e instanceof RegistrationException)return ResponseUtil.error(e.getMessage().equals("Registration not found")?404:409,"REGISTRATION_ERROR",e.getMessage());return ResponseUtil.error(500,"INTERNAL_ERROR","Internal server error");}
}
